INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A dye bath achieves 92% exhaustion for a recipe using 3% owf dye on a 400 kg fabric batch. Approximately how much dye (in kg) remains UNEXHAUSTED in the residual liquor?', '["≈ 0.96 kg","≈ 12 kg","≈ 11.04 kg","≈ 3 kg"]'::jsonb, '≈ 0.96 kg', 'Total dye used = 0.03 × 400 kg = 12 kg. Exhausted = 92% of 12 kg = 11.04 kg. Unexhausted (remaining in liquor) = 12 − 11.04 = 0.96 kg.', 2, '{"dye-exhaustion-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A dye bath achieves 95% exhaustion for a recipe using 2% owf dye on a 600 kg fabric batch. Approximately how much dye (in kg) remains UNEXHAUSTED in the residual liquor?', '["≈ 0.6 kg","≈ 12 kg","≈ 11.4 kg","≈ 2 kg"]'::jsonb, '≈ 0.6 kg', 'Total dye used = 0.02 × 600 kg = 12 kg. Exhausted = 95% of 12 kg = 11.4 kg. Unexhausted = 12 − 11.4 = 0.6 kg.', 2, '{"dye-exhaustion-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A finishing chemical recipe calls for 30 g/L of a softener at a liquor ratio of 1:15 for a 100 kg fabric batch. How many kg of softener chemical are needed?', '["45 kg","30 kg","15 kg","4.5 kg"]'::jsonb, '45 kg', 'Total liquor = 15 × 100 kg = 1,500 liters. Total softener = 30 g/L × 1,500 L = 45,000 g = 45 kg.', 2, '{"chemical-dosing-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A finishing chemical recipe calls for 25 g/L of a softener at a liquor ratio of 1:12 for a 200 kg fabric batch. How many kg of softener chemical are needed?', '["60 kg","25 kg","12 kg","5 kg"]'::jsonb, '60 kg', 'Total liquor = 12 × 200 kg = 2,400 liters. Total softener = 25 g/L × 2,400 L = 60,000 g = 60 kg.', 2, '{"chemical-dosing-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A shade-matching lab dip uses 0.05 g of dye for a 5 g fabric sample. What percentage owf (on weight of fabric) does this represent?', '["1%","0.05%","5%","10%"]'::jsonb, '1%', '%owf = (dye weight / fabric weight) × 100 = (0.05 / 5) × 100 = 1%.', 2, '{"owf-back-calculation"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'A shade-matching lab dip uses 0.08 g of dye for a 4 g fabric sample. What percentage owf does this represent?', '["2%","0.08%","8%","0.5%"]'::jsonb, '2%', '%owf = (dye weight / fabric weight) × 100 = (0.08 / 4) × 100 = 2%.', 2, '{"owf-back-calculation"}'::text[]);
